//****************************************************************
// DudoGame class
//****************************************************************
export class DudoGame {

	curRound;	// one DudoRound object
	Rounds = []; // array of DudoRound objects

	startDate = '';
	startTime = '';
	endDate = '';
	endTime = '';

	// associated arrays
	allConnectionID = [];
	allConnectionStatus = [];
	allParticipantGuid = [];
	allParticipantNames = [];
	allSticks = [];
	allPasoUsed = [];
	// for testing &&& keep track of each player's setting
	// 0 = dropdown list
	// 1 = grid
	allBidUIMode = [];
			
	// game parameters
	maxSticks;
	bPasoAllowed;
	bPaloFijoAllowed;
	bPaloFijoRound;

	// these java definitions are now defined in the construtor
	//dice = [][];                
	//diceHidden = [][];      
	//diceHilite = [][];
	//BidMatrix = [][];   

// new GAME_PHASE to eventually replace bools
	gamePhase;
	GAME_IN_PROGRESS

	firstRound;
	bSettingGameParms;
	bBlinkSticks;
	bBlinkSticksPlayer;
	
	inOutMustSay = [];
	inOutDidSay = [];
  doubtMustLiftCup = [];
  doubtDidLiftCup = [];
	nextRoundMustSay = [];
	nextRoundDidSay = [];

	whosTurn;                
	whosTurnPrev;            
	
	// for building possible bids list
	parsedHowMany;
	parsedOfWhat;
	possibleBids = [];

	bWinnerRound;
	bWinnerGame;
	whoWonGame;
	orderOfFinish = [];

	bDisconnectPause;
	disconnectPausedPlayerName;
	disconnectSecondsRemaining;

	//****************************************************************
	// constructor
	//****************************************************************
	constructor() {
		this.curRound = null;

		for (let cc = 0; cc < MAX_CONNECTIONS; cc++) {
			this.allParticipantNames[cc] = '';
			this.allParticipantGuid[cc] = '';
			this.allConnectionID[cc] = '';
			this.allConnectionStatus[cc] = CONN_UNUSED;
			this.allSticks[cc] = 0;
			this.allPasoUsed[cc] = false;
			this.allBidUIMode[cc] = 0;
		}

		// default game parameters
		this.maxSticks = 1;
		this.bPasoAllowed = true;
		this.bPaloFijoAllowed = true;
		this.bPaloFijoRound =  false;
		
		this.dice = new Array(MAX_CONNECTIONS);
		for (let i = 0; i < MAX_CONNECTIONS; i++) {
			this.dice[i] = new Array(5);
		}
		this.bDiceHidden = new Array(MAX_CONNECTIONS);
		for (let i = 0; i < MAX_CONNECTIONS; i++) {
			this.bDiceHidden[i] = new Array(5);
		}

		this.bDiceHilite = new Array(MAX_CONNECTIONS);
		for (let i = 0; i < MAX_CONNECTIONS; i++) {
			this.bDiceHilite[i] = new Array(5);
		}

		this.BidMatrix = new Array(5 * MAX_PLAYERS);
		for (let i = 0; i < 5 * MAX_PLAYERS; i++) {
			this.BidMatrix[i] = new Array(6).fill(false);
		}

		this.setGamePhase(GAME_PHASE.WAITING_TO_START);

		this.bSettingGameParms = false;
		this.bBlinkSticks = false;
		this.bBlinkSticksPlayer = undefined;

		this.bWinnerRound = false;
		this.bWinnerGame = false;
		this.whoWonGame = undefined;
		this.whosTurn = -1;

		this.bDisconnectPause = false;
		this.disconnectPausedPlayerName = '';
		this.disconnectSecondsRemaining = 0;		
	}

	//****************************************************************
	// Shift game slots left (delete)
	//****************************************************************
	shiftGameSlotsLeft(index) {
		if (index < 0) return;

		for (let cc = index; cc < MAX_CONNECTIONS - 1; cc++) {

			this.allParticipantGuid[cc]  = this.allParticipantGuid[cc + 1];
			this.allParticipantNames[cc] = this.allParticipantNames[cc + 1];
			this.allConnectionID[cc]     = this.allConnectionID[cc + 1];
			this.allConnectionStatus[cc] = this.allConnectionStatus[cc + 1];

			this.allSticks[cc]    = this.allSticks[cc + 1];
			this.allPasoUsed[cc]  = this.allPasoUsed[cc + 1];
			this.allBidUIMode[cc] = this.allBidUIMode[cc + 1];

			this.dice[cc]        = [...this.dice[cc + 1]];
			this.bDiceHidden[cc] = [...this.bDiceHidden[cc + 1]];
			this.bDiceHilite[cc] = [...this.bDiceHilite[cc + 1]];

			this.inOutMustSay[cc] = this.inOutMustSay[cc + 1];
			this.inOutDidSay[cc]  = this.inOutDidSay[cc + 1];

			this.doubtMustLiftCup[cc] = this.doubtMustLiftCup[cc + 1];
			this.doubtDidLiftCup[cc]  = this.doubtDidLiftCup[cc + 1];

			this.nextRoundMustSay[cc] = this.nextRoundMustSay[cc + 1];
			this.nextRoundDidSay[cc]  = this.nextRoundDidSay[cc + 1];
		}

		this.clearGameSlot(MAX_CONNECTIONS - 1);

		if (this.whosTurn > index) {
			this.whosTurn--;
		} else if (this.whosTurn === index) {
			this.whosTurn = -1;
		}

		if (this.whosTurnPrev > index) {
			this.whosTurnPrev--;
		} else if (this.whosTurnPrev === index) {
			this.whosTurnPrev = -1;
		}
	}

	//****************************************************************
	// Clear a game slot
	//****************************************************************
	clearGameSlot(index) {
		if (index < 0) return;

		this.allParticipantGuid[index]  = '';
		this.allParticipantNames[index] = '';
		this.allConnectionID[index]     = '';
		this.allConnectionStatus[index] = CONN_UNUSED;

		this.allSticks[index]    = 0;
		this.allPasoUsed[index]  = false;
		this.allBidUIMode[index] = 0;

		this.dice[index]        = Array(5).fill(0);
		this.bDiceHidden[index] = Array(5).fill(false);
		this.bDiceHilite[index] = Array(5).fill(false);

		this.inOutMustSay[index] = false;
		this.inOutDidSay[index]  = false;

		this.doubtMustLiftCup[index] = false;
		this.doubtDidLiftCup[index]  = false;

		this.nextRoundMustSay[index] = false;
		this.nextRoundDidSay[index]  = false;
	}

	//************************************************************
	// Fill up this instance of DudoGame from
	// the instance passed from the server
	//************************************************************
	AssignGameState(state) {
		console.log('DudoGame: Entering AssignGameState()');

		if (!state || typeof state !== 'object' || Object.keys(state).length === 0) {
			console.error('AssignGameState: Received invalid or empty state:', state);
			return;
		}

		Object.assign(this, state);

		// Always reset curRound explicitly
  	this.curRound = null;

		// Rehydrate current round
		if (state.curRound) {
			this.curRound = new DudoRound();
			Object.assign(this.curRound, state.curRound);

			if (Array.isArray(state.curRound.Bids)) {
				this.curRound.Bids = state.curRound.Bids.map((bid) => {
					const newBid = new DudoBid();
					Object.assign(newBid, bid);
					return newBid;
				});
			}
		}

		// Always reset Rounds explicitly too
	  this.Rounds = [];

		// Rehydrate rounds history
		if (Array.isArray(state.Rounds)) {
			this.Rounds = state.Rounds.map((round) => {
				const newRound = new DudoRound();
				Object.assign(newRound, round);

				if (Array.isArray(round.Bids)) {
					newRound.Bids = round.Bids.map((bid) => {
						const newBid = new DudoBid();
						Object.assign(newBid, bid);
						return newBid;
					});
				}

				return newRound;
			});
		}
	}

	//************************************************************
	// initialize game parameters
	//************************************************************
	PrepareNextGame () {
		this.curRound = null;

		this.bPasoAllowed = true;
		this.bPaloFijoAllowed = true;
		this.bPaloFijoRound =  false;
		this.firstRound = true;

		this.setGamePhase(GAME_PHASE.WAITING_TO_START);

		this.bSettingGameParms = false;
		this.bBlinkSticks = false;
		this.bBlinkSticksPlayer = undefined;
		
		this.bWinnerRound = false;
		this.bWinnerGame = false;
		this.whoWonGame = undefined;
		this.whosTurn = -1;

		// chatgpt added these
		this.inOutMustSay = Array(MAX_CONNECTIONS).fill(false);
		this.inOutDidSay = Array(MAX_CONNECTIONS).fill(false);
		this.doubtMustLiftCup = Array(MAX_CONNECTIONS).fill(false);
		this.doubtDidLiftCup = Array(MAX_CONNECTIONS).fill(false);
		this.nextRoundMustSay = Array(MAX_CONNECTIONS).fill(false);
		this.nextRoundDidSay = Array(MAX_CONNECTIONS).fill(false);
		this.orderOfFinish = [];
		this.possibleBids = [];
		this.parsedHowMany = undefined;
		this.parsedOfWhat = undefined;
		this.curRound = undefined;		

		for (let i = 0; i < MAX_CONNECTIONS; i++) {
			const status = this.allConnectionStatus[i];
			//&&&if (status === CONN_PLAYER_IN || status === CONN_PLAYER_OUT || status === CONN_OBSERVER) {
			if (status === CONN_PLAYER_IN || status === CONN_PLAYER_OUT) {
				this.allConnectionStatus[i] = CONN_PLAYER_IN;
			}
			this.allPasoUsed[i] = false;
			this.allSticks[i] = 0;
		}

		this.Rounds.length = 0;

		for (let i=0; i < MAX_CONNECTIONS; i++) {
			for (let j=0; j < 5; j++) {
				this.dice[i][j] = undefined;
				this.bDiceHidden[i][j] = true;
				this.bDiceHilite[i][j] = false;
			}
		}
	}

	//************************************************************
	// set the game phase parameters
	//************************************************************
	setGamePhase(phase) {
		this.gamePhase = phase;

		if (
			phase === GAME_PHASE.ASKING_IN_OUT ||
			phase === GAME_PHASE.CHOOSING_DIRECTION ||
			phase === GAME_PHASE.BIDDING ||
			phase === GAME_PHASE.DOUBT_LIFT_CUPS ||
			phase === GAME_PHASE.DOUBT_SHOW_RESULT ||
			phase === GAME_PHASE.BETWEEN_ROUNDS
		) {
			this.GAME_IN_PROGRESS = true;
		} else {
			this.GAME_IN_PROGRESS = false;
		}
	}

	//************************************************************
	// figure out who goes next
	//************************************************************
	getWhosTurnNext () {
		if (this.curRound.whichDirection === 1) {
			return this.getPlayerToLeft(this.whosTurn);
		} else {
			return this.getPlayerToRight(this.whosTurn);
		}
	}

	//************************************************************
	// get player to the left
	//************************************************************
	getPlayerToLeft(cc) {
		for (let i = 0; i < MAX_CONNECTIONS; i++) {
			cc = (cc + 1) % MAX_CONNECTIONS;
			if (this.allConnectionStatus[cc] === CONN_PLAYER_IN) {
				return cc;
			}
		}
		return -1;
	}

	//************************************************************
	// get player to the right
	//************************************************************
	getPlayerToRight(cc) {
		for (let i = 0; i < MAX_CONNECTIONS; i++) {
			cc = (cc - 1 + MAX_CONNECTIONS) % MAX_CONNECTIONS;
			if (this.allConnectionStatus[cc] === CONN_PLAYER_IN) {
				return cc;
			}
		}
		return -1;
	}

	//************************************************************
	// figure out doubt result
	//************************************************************
	getDoubtResult () {
		this.curRound.doubtedText = this.curRound.Bids[this.curRound.numBids - 2].text;
		this.curRound.whoDoubted = this.curRound.Bids[this.curRound.numBids - 1].playerIndex;
		this.curRound.whoGotDoubted = this.curRound.Bids[this.curRound.numBids - 2].playerIndex;
		//--------------------------------------------------------
		// doubted paso
		//--------------------------------------------------------
		if (this.curRound.Bids[this.curRound.numBids - 2].bPaso) {
			this.curRound.doubtWasPaso = true;
			this.curRound.doubtHowMany = 0;
			this.curRound.doubtOfWhat = 0;
			// determine winner and loser
			if (this.hasPaso()) {
				this.curRound.doubtLoser = this.curRound.whoDoubted;
				this.curRound.doubtWinner = this.curRound.whoGotDoubted;
				this.curRound.doubtPasoWasThere = true;
			}
			else {
				this.curRound.doubtLoser = this.curRound.whoGotDoubted;
				this.curRound.doubtWinner = this.curRound.whoDoubted;
				this.curRound.doubtPasoWasThere = false;
			}
			// is the loser palofijo?
			this.curRound.doubtLoserPaloFijo = false;
			if (this.bPaloFijoAllowed &&
				this.GetNumberPlayersStillIn() > 2 &&
				this.allSticks[this.curRound.doubtLoser] === this.maxSticks - 2) {
				this.curRound.doubtLoserPaloFijo = true;
			}
			// is the loser out?
			if (this.allSticks[this.curRound.doubtLoser] === this.maxSticks - 1) {
				this.curRound.doubtLoserOut = true;
			} else {
				this.curRound.doubtLoserOut = false;
			}
			// did somebody win the game?
			// we won't actually assign the stick and make the player out until PostRound()
			// This is so it doesn't show in the UI prematurely
			if (this.GetNumberPlayersStillIn() === 2 && this.curRound.doubtLoserOut) {
				this.bWinnerGame = true;
				this.whoWonGame = this.curRound.doubtWinner;
			}
			return;
		}

		//------------------------------------------------------------
		// doubted non-paso bid
		//------------------------------------------------------------
		this.curRound.doubtHowMany = this.curRound.Bids[this.curRound.numBids - 2].howMany;
		this.curRound.doubtOfWhat = this.curRound.Bids[this.curRound.numBids - 2].ofWhat;
		this.curRound.doubtShowing = this.GetHowManyShowing(this.curRound.doubtOfWhat, this.bPaloFijoRound);
		this.curRound.doubtLookingFor = this.curRound.doubtHowMany - this.curRound.doubtShowing;
		if (this.curRound.doubtLookingFor < 0) {
			this.curRound.doubtLookingFor = 0;
		}
	
		if (this.bPaloFijoRound) {
			//--------------------------------------------------------
			// palo fijo, aces are not wild
			//--------------------------------------------------------
			this.curRound.doubtWasPaso = false;
			this.curRound.doubtCount = 0;
			for (let cc = 0; cc < MAX_CONNECTIONS; cc++) {
				if (this.allConnectionStatus[cc] === CONN_PLAYER_IN) {
					for (let j = 0; j < 5; j++) {
						if (this.dice[cc][j] === this.curRound.doubtOfWhat) {
							this.curRound.doubtCount++;
							this.bDiceHilite[cc][j] = true;
						}
					}
				}
			}
				
		} else {
			//--------------------------------------------------------
			// regular round
			//--------------------------------------------------------
			if (this.curRound.doubtOfWhat === 1) {
				//----------------------------------------------------
				// doubted aces, or palofijo round
				// i.e. don't count aces as wildcards
				//----------------------------------------------------
				this.curRound.doubtWasPaso = false;
				this.curRound.doubtCount = 0;
				for (let cc = 0; cc < MAX_CONNECTIONS; cc++) {
					if (this.allConnectionStatus[cc] === CONN_PLAYER_IN) {
						for (let j = 0; j < 5; j++) {
							if (this.dice[cc][j] === this.curRound.doubtOfWhat) {
								this.curRound.doubtCount++;
								this.bDiceHilite[cc][j] = true;
							}
						}
					}
				}
			}
			if (this.curRound.doubtOfWhat !== 1) {
				//----------------------------------------------------
				// doubted non-aces
				//----------------------------------------------------
				this.curRound.doubtWasPaso = false;
				this.curRound.doubtCount = 0;
				for (let cc = 0; cc < MAX_CONNECTIONS; cc++) {
					if (this.allConnectionStatus[cc] === CONN_PLAYER_IN) {
						for (let j = 0; j < 5; j++) {
							if ((this.dice[cc][j] === this.curRound.doubtOfWhat)|| this.dice[cc][j] === 1){
								this.curRound.doubtCount ++;
								this.bDiceHilite[cc][j] = true;
							}
						}
					}
				}
			}
		}

		//------------------------------------------------------------
		// determine winner and loser
		//------------------------------------------------------------
		if (this.curRound.doubtCount < this.curRound.doubtHowMany) {
			// the bid is not there
			this.curRound.doubtLoser = this.curRound.whoGotDoubted;
			this.curRound.doubtWinner = this.curRound.whoDoubted;
		} else {
			// the bid is there
			this.curRound.doubtLoser = this.curRound.whoDoubted;
			this.curRound.doubtWinner = this.curRound.whoGotDoubted;
		}

		//------------------------------------------------------------
		// is the loser palofijo?
		//------------------------------------------------------------
		this.curRound.doubtLoserPaloFijo = false;
		if (this.bPaloFijoAllowed &&
			this.GetNumberPlayersStillIn() > 2 &&
			this.allSticks[this.curRound.doubtLoser] === this.maxSticks - 2) {
			this.curRound.doubtLoserPaloFijo = true;
		}

		//------------------------------------------------------------
		// is the loser out?
		//------------------------------------------------------------
		if (this.allSticks[this.curRound.doubtLoser] === this.maxSticks - 1) {
			this.curRound.doubtLoserOut = true;
		} else {
			this.curRound.doubtLoserOut = false;
		}

		//------------------------------------------------------------
		// did somebody win the game?
		// we won't actually assign the stick and make the player out until PostRound()
		// This is so it doesn't show in the UI prematurely
		//------------------------------------------------------------
		if (this.GetNumberPlayersStillIn() === 2 && this.curRound.doubtLoserOut) {
			this.bWinnerGame = true;
			this.whoWonGame = this.curRound.doubtWinner;
		}
	}

	//************************************************************
	// fill in list of who needs to lift their cup
	// this is 'true' or 'false' for each participant
	//************************************************************
	getMustLiftCupList () {
		// initialize all to false
		for (let i=0; i<MAX_CONNECTIONS; i++) {
			this.doubtMustLiftCup[i] = false;
		}

		// if PASO, only the one who was doubted
		if (this.curRound.doubtWasPaso) {
			this.doubtMustLiftCup[this.curRound.whoGotDoubted] = true;
			return;
		}
		
		// not PASO, all players who are IN
		for (let i=0; i<MAX_CONNECTIONS; i++) {
			if (this.allConnectionStatus[i] === CONN_PLAYER_IN) {
				this.doubtMustLiftCup[i] = true;
			}
		}
		// if UNUSED or OBSERVER, false
	}

	//************************************************************
	// fill in list of who needs to say in or out
	// this is 'true' or 'false' for each participant
	//************************************************************
	getInOutMustSay () {
		for (let i=0; i<MAX_CONNECTIONS; i++) {
			let st = this.allConnectionStatus[i];
			//&&&if (st === CONN_PLAYER_IN || st === CONN_PLAYER_OUT || st === CONN_OBSERVER) {
			if (st === CONN_PLAYER_IN || st === CONN_PLAYER_OUT) {
				this.inOutMustSay[i] = true;
			} else {
				this.inOutMustSay[i] = false;
			}
		}
	}

	//************************************************************
	// fill in list of who needs to say ok for next round
	// this is 'true' or 'false' for each participant
	//************************************************************
	getNextRoundMustSay () {
		for (let i=0; i<MAX_CONNECTIONS; i++) {
			let st = this.allConnectionStatus[i];
			if (st === CONN_PLAYER_IN) {
				this.nextRoundMustSay[i] = true;
			} else {
				this.nextRoundMustSay[i] = false;
			}
		}
	}

	//************************************************************
	// reset all who must say back to false(did not say)
	// this is used when a player times out during SHOWING_RESULT
	//************************************************************
	resetNextRoundDidSay () {
		for (let i=0; i<MAX_CONNECTIONS; i++) {
			let status = this.allConnectionStatus[i];
			if ((status === CONN_PLAYER_IN) || (status === CONN_PLAYER_TIMED_OUT)) {
				if (this.nextRoundMustSay[i]) {
					this.nextRoundDidSay[i] = false;
				}
			}
		}
	}

	//************************************************************
	// does the doubted player have the paso?
	//************************************************************
	hasPaso() {
		// int array of frequencies of each of the six numbers
		let freq = Array(6).fill(0);

		// populate frequences of each die
		for (let i = 0; i < 5; i++) {
			let die = this.dice[this.curRound.whoGotDoubted][i]; 
			freq[die - 1]++;
		}

		// all five the same?
		for (let i = 0; i < 6; i++) {
			if (freq[i] === 5) {
				return true;
			}
		}
		// all five the different?
		let bAllDifferent = true;
		for (let i = 0; i < 6; i++) {
			if (freq[i] > 1) {
				bAllDifferent = false;
				break;
			}
		}
		if (bAllDifferent) {
			return true;
		}
		// full house?
		let c2 = 0;
		let c3 = 0;
		for (let i = 0; i < 6; i++) {
			if (freq[i] === 2) {
				c2++;
			}
			if (freq[i] === 3) {
				c3++;
			}
		}
		if ((c2 === 1) && (c3 === 1)) {
			return true;
		}

		// none of the above
		return false;
	}

	//****************************************************************
	// Populate possible bid list REGULAR
	//****************************************************************
	PopulateBidListRegular() {

		console.log('DudoGame: Entering PopulateBidListRegular()');
		
		//------------------------------------------------------------
		// initialize possible bid list
		//------------------------------------------------------------
		this.possibleBids.length = 0;
		this.possibleBids.push("--Select--");
		let bidStr = '';

		//------------------------------------------------------------
		// special case of first bid
		//------------------------------------------------------------
		if (this.curRound.numBids === 0) {
			this.PopulateBidListFirstBid();
			return;
		}

		//------------------------------------------------------------
		//  this is not the first bid
		//------------------------------------------------------------
		// get and parse current bid
		// (parsed into parsedHowMany and parsedOfWhat)
		//------------------------------------------------------------
		if (this.curRound.Bids[this.curRound.numBids - 1].bPaso) {
			let lastNonPaso = this.FindLastNonPasoBid();
			this.parseBid(this.curRound.Bids[lastNonPaso].text);
		} else {
			this.parseBid(this.curRound.Bids[this.curRound.numBids - 1].text);
		}

		//------------------------------------------------------------
		// special case:  opening aces bid, then all PASOs
		// no double plus one, only simple top bid
		//------------------------------------------------------------
		if (this.curRound.Bids[this.curRound.numBids - 1].bPaso) {
			if (this.parsedOfWhat === 1) {
				if (this.FindLastNonPasoBid() === 0) {
					for (let i = 0; i < (5 * this.GetNumberPlayersStillIn()) - this.parsedHowMany; i++) {
						// list non-aces first
						for (let j = 1; j < 6; j++) {
							bidStr = this.GenerateBidString (this.parsedHowMany + 1 + i, j + 1);
							this.possibleBids.push(bidStr);
						}
						// then put aces after
						bidStr = this.GenerateBidString (this.parsedHowMany + 1 + i, 1);
						this.possibleBids.push(bidStr);
					}
					return;
				}
			}
		}

		//------------------------------------------------------------
		// generate possible bids
		//------------------------------------------------------------
		if (this.parsedOfWhat !== 1) {
				//--------------------------------------------------------
				// Non-aces bid
				//--------------------------------------------------------
				// baja de aces bids
				for (let i = 0; i < Math.floor(this.parsedHowMany / 2); i++) {
					const temp = Math.floor(this.parsedHowMany / 2) + (this.parsedHowMany) % 2 + i;
					bidStr = this.GenerateBidString (temp, 1);
					this.possibleBids.push(bidStr);
				}
				// same level bids
				// list non-aces first
				for (let i = 0; i < 6 - this.parsedOfWhat; i++) {
					bidStr = this.GenerateBidString (this.parsedHowMany, (this.parsedOfWhat + 1 + i));
					this.possibleBids.push(bidStr);
				}
				// then put aces after
				bidStr = this.GenerateBidString(this.parsedHowMany, 1);			
				this.possibleBids.push(bidStr);
				
				// next level bids
				for (let howMany = 0; howMany < (5 * this.GetNumberPlayersStillIn()) - this.parsedHowMany; howMany++) {
					// list non-aces first
					for (let j = 1; j < 6; j++) {
						bidStr = this.GenerateBidString(this.parsedHowMany + 1 + howMany, j +1);
						this.possibleBids.push(bidStr);
					}
					// then put aces after
					bidStr = this.GenerateBidString(this.parsedHowMany + 1 + howMany, 1)
					this.possibleBids.push(bidStr);
				}
		} else {
				//--------------------------------------------------------
				// aces bid
				//--------------------------------------------------------
				if (this.curRound.numBids === 1) {
					// special case, no double plus one after first bid
					for (let i = 0; i < (5 * this.GetNumberPlayersStillIn()) - this.parsedHowMany; i++) {
						// list non-aces first
						for (let j = 1; j < 6; j++) {
							bidStr = this.GenerateBidString(this.parsedHowMany + 1 + i, j + 1)
							this.possibleBids.push(bidStr);
						}
						// then put aces after
						bidStr = this.GenerateBidString(this.parsedHowMany + 1 + i, 1)
						this.possibleBids.push(bidStr);
					}
				} else {
					// raise aces bid
					for (let i = 0; i < this.parsedHowMany; i++) {
						let numAces = this.parsedHowMany + 1 + i;
						if (numAces > 5 * this.GetNumberPlayersStillIn()) {
							break;
						}
						bidStr = this.GenerateBidString(numAces, 1);
						this.possibleBids.push(bidStr);
				}
				// next level bids (double + 1)
				for (let i = 0; i < (5 * this.GetNumberPlayersStillIn()) - ( 2 * this.parsedHowMany); i++) {
					// list non-aces first
					for (let j = 1; j < 6; j++) {
						bidStr = this.GenerateBidString(2 * this.parsedHowMany + 1 + i, j + 1);
						this.possibleBids.push(bidStr);
					}
					// then put aces after
					bidStr = this.GenerateBidString(2 * this.parsedHowMany + 1 + i, 1)
					this.possibleBids.push(bidStr);
				}
			}
		}

		//&&& testing
/*		
		const testString1 = "1 - \u2680";
		const testString2 = "1 - \u2681";
		const testString3 = "1 - \u2682";
		const testString4 = "1 - \u2683";
		const testString5 = "1 - \u2684";
		const testString6 = "1 - \u2685";
*/

	}

	//****************************************************************
	// Populate possible bid list PALOFIJO
	//****************************************************************
	PopulateBidListPaloFijo() {

		console.log('DudoGame: Entering PopulateBidListPaloFijo()');
		
		//------------------------------------------------------------
		// initialize possible bid list
		//------------------------------------------------------------
		this.possibleBids.length = 0;
		this.possibleBids.push("--Select--");
		let bidStr = '';

		//------------------------------------------------------------
		// special case of first bid
		//------------------------------------------------------------
		if (this.curRound.numBids === 0) {
			this.PopulateBidListFirstBid();
			return;
		}

		//------------------------------------------------------------
		//  this is not the first bid
		//------------------------------------------------------------
		// get and parse current bid
		// (parsed into parsedHowMany and parsedOfWhat)
		//------------------------------------------------------------
		if (this.curRound.Bids[this.curRound.numBids - 1].bPaso) {
			let lastNonPaso = this.FindLastNonPasoBid();
			this.parseBid(this.curRound.Bids[lastNonPaso].text);
		} else {
			this.parseBid(this.curRound.Bids[this.curRound.numBids - 1].text);
		}

		//------------------------------------------------------------
		// generate (and count) possible bids
		//------------------------------------------------------------
		if (this.IsPaloFijo(this.whosTurn)) {
			//--------------------------------------------------------
			// I am PaloFijo
			// I can change the bid
			//--------------------------------------------------------

			if (this.parsedOfWhat !== 1) {
				//--------------------------------------------------------
				// Non-aces bid
				//--------------------------------------------------------
				// same level bids
				for (let i = 0; i < 6 - this.parsedOfWhat; i++) {
					bidStr = this.GenerateBidString(this.parsedHowMany, this.parsedOfWhat + 1 + i);
					this.possibleBids.push(bidStr);
				}
				// put aces after the rest (aces are highest in palofijo)
				bidStr = this.GenerateBidString(this.parsedHowMany, 1)
				this.possibleBids.push(bidStr);

				// next level bids
				for (let i = 0; i < (5 * this.GetNumberPlayersStillIn()) - this.parsedHowMany; i++) {
					for (let j = 1; j < 6; j++) {
						bidStr = this.GenerateBidString(this.parsedHowMany + 1 + i, j + 1);
						this.possibleBids.push(bidStr);
					}
					// aces on top
					bidStr = this.GenerateBidString(this.parsedHowMany + 1 + i, 1);
					this.possibleBids.push(bidStr);
				}
		} else {
			//--------------------------------------------------------
			// aces bid
			//--------------------------------------------------------
			// raise aces bid
			for (let i = 0; i < this.parsedHowMany - 1; i++) {
				bidStr = this.GenerateBidString(this.parsedHowMany + 1 + i, 1);
				this.possibleBids.push(bidStr);
			}
			// next level bids
			for (let i = 0; i < (5 * this.GetNumberPlayersStillIn()) - this.parsedHowMany; i++) {
				for (let j = 1; j < 6; j++) {
					bidStr = this.GenerateBidString(this.parsedHowMany + 1 + i, j + 1);
					this.possibleBids.push(bidStr);
				}
				// aces on top
				bidStr = this.GenerateBidString(this.parsedHowMany + 1 + i, 1);
				this.possibleBids.push(bidStr);
			}
		}
	} else {
			//--------------------------------------------------------
			// I'm not palofijo
			// I can only raise or doubt
			//--------------------------------------------------------
			for (let i = this.parsedHowMany; i < this.GetNumberPlayersStillIn() * 5; i++) {
				bidStr = this.GenerateBidString(i + 1, this.parsedOfWhat);
				this.possibleBids.push(bidStr);
			}
		}
	}

	//****************************************************************
	// Populate bid list -- first bid
	//****************************************************************
	PopulateBidListFirstBid() {
		let sTemp;		
		for (let howMany = 0; howMany < this.GetNumberPlayersStillIn() * 5; howMany++) {
			// list non-aces first
			for (let ofWhat = 1; ofWhat < 6; ofWhat++) {
				sTemp = this.GenerateBidString(howMany  + 1, ofWhat + 1);
				this.possibleBids.push(sTemp);
			}
			// then put aces after
			sTemp = this.GenerateBidString(howMany + 1, 1);
			this.possibleBids.push(sTemp);
		}
	}

	//****************************************************************
	// PopulateBidMatrix
	//****************************************************************
	PopulateBidMatrix () {
		// initialize 
		this.BidMatrix.length = 0; // clear existing contents
		for (let i = 0; i < 5 * this.GetNumberPlayersStillIn(); i++) {
			this.BidMatrix[i] = [];
			for (let j = 0; j < 6; j++) {
				this.BidMatrix[i][j] = false;
			}
		}
		// fill in from possibleBids
		for (let i=1; i<this.possibleBids.length; i++) {		// start from 1 to avoid --Select--
			this.parseBid (this.possibleBids[i]);
			const row = this.parsedHowMany - 1;
			const col = (this.parsedOfWhat === 1 ? 5: this.parsedOfWhat - 2);	// aces go at the end
			this.BidMatrix[row][col] = true;
		}
	}

	//****************************************************************
	// Generate bid string
	//	inputs:  number, face
	//	output:  string of form (a - b)
	//****************************************************************
	GenerateBidString (num, face) {
		let str = '';

		if (face === 1) {
			str = num.toString() + " - ace";
		} else {
			str = num.toString() + " - " + face.toString();
		}
		if (num > 1) {
			str += 's';
		}
		return str;
	}

	//****************************************************************
	// Extract from bid string (inverse of GenerateBidString())
	//	inputs:  string of form '(a - b)'
	//	output:  2 integers: number, face (as an object)
	//****************************************************************
	ExtractBidString(bidString) {
		let num = 0;
		let face = 0;
		let str = bidString;

		// remove trailing 's'
		if (str.endsWith('s')) {
			str = str.slice(0, -1);
		}

		// split the cleaned string
		const sSplit = str.split(" ");
		if (sSplit.length === 3) {
			num = Number(sSplit[0]);  
			face = (sSplit[2] === "ace") ? 1 : Number(sSplit[2]);
		}

		return [num, face];
	}

	//****************************************************************
	// Trim the bid list (1 - aces) => (1 - ace)
	//****************************************************************
	PopulateBidListTrim () {
		for (let i = 0; i < this.possibleBids.length; i++) {
			if (this.possibleBids[i] === "1 - aces") {
				this.possibleBids[i] = "1 - ace";
			}
		}
	}

	//****************************************************************
	// Parse the bid string into integers
	//****************************************************************
	parseBid(s) {
		const sSplit = s.split(" ");
		let len = sSplit.length;
		if (len === 3) {
			this.parsedHowMany = parseInt(sSplit[0]);  
			if ((sSplit[2] === "aces") || (sSplit[2] === "ace")) {
				this.parsedOfWhat = 1;
			} else {
				this.parsedOfWhat = parseInt(sSplit[2]);
			}
		} 
	}

	//****************************************************************
	// Find last non paso bid
	// (must be at least two bids made already)
	//****************************************************************
	FindLastNonPasoBid () {
		for (let i = this.curRound.numBids - 2; i >= 0; i--) {
			if (!this.curRound.Bids[i].bPaso) {
				return i;
			}
		}
		console.log('ERROR cannot find last non-paso bid');
		return (-1);
	}

	//****************************************************************
	// Get number of players in the lobby (and connected)
	//  IN, OUT, OBSERVER
	//****************************************************************
	GetNumberPlayersInLobby () {
		let result = 0;
		for (let cc = 0; cc < MAX_CONNECTIONS; cc++) {
			if (this.allConnectionStatus[cc] === CONN_PLAYER_IN ||
				this.allConnectionStatus[cc] === CONN_PLAYER_OUT ||
				this.allConnectionStatus[cc] === CONN_OBSERVER) {
				result++;
			}
		}
		return result;
	}

	//****************************************************************
	// Get number of players playing this game
	//  IN, OUT
	//****************************************************************
	GetNumberPlayersPlaying () {
		let result = 0;
		for (let cc = 0; cc < MAX_CONNECTIONS; cc++) {
			if (this.allConnectionStatus[cc] === CONN_PLAYER_IN ||
				this.allConnectionStatus[cc] === CONN_PLAYER_OUT) {
				result++;
			}
		}
		return result;
	}

	//****************************************************************
	// Get number of players still in
	//  IN
	//****************************************************************
	GetNumberPlayersStillIn () {
		let result = 0;
		for (let cc = 0; cc < MAX_CONNECTIONS; cc++) {
			if (this.allConnectionStatus[cc] === CONN_PLAYER_IN) {
				result++;
			}
		}
		return result;
	}

	//****************************************************************
	// Get index of first player still in
	//  index of first IN
	//****************************************************************
	GetIndexFirstPlayerStillIn () {
		for (let cc = 0; cc < MAX_CONNECTIONS; cc++) {
			if (this.allConnectionStatus[cc] === CONN_PLAYER_IN) {
				return cc;
			}
		}
		// this should never happen
		console.log('ERROR: GetIndexFirstPlayersStillIn() - no players still in');
		return undefined;
	}

	//****************************************************************
	// Can we PASO?
	//****************************************************************
	CanPaso () {
		// can't paso if not allowed by game setting
		if (!this.bPasoAllowed) {
			return false;
		}
		// can't paso on first bid
		if (this.curRound.numBids === 0) {
			return false;
		}
		// can't paso twice in the same wound
		if (this.allPasoUsed[this.whosTurn]) {
			return false;
		}

		if (this.bPaloFijoRound) {
			// only palofijos can paso in palofijo round
			return (this.IsPaloFijo(this.whosTurn));
		} else {
			// otherwise ok
			return (true);
		}
	}

	//****************************************************************
	// Is this player palofijo?
	//****************************************************************
	IsPaloFijo (cc) {
		if (!this.bPaloFijoRound) {
			return false;
		}
		if (this.allSticks[cc] === this.maxSticks - 1) {
			return true;
		} else {
			return false;
		}
	}

	//****************************************************************
	// Get how many showing
	//****************************************************************
	GetHowManyShowing (ofWhat, bPaloFijo) {
		let result = 0;
		for (let cc = 0; cc < MAX_CONNECTIONS; cc++) {
			if (this.allConnectionStatus[cc] === CONN_PLAYER_IN ||
				  this.allConnectionStatus[cc] === CONN_PLAYER_TIMED_OUT_DEFER) {
				for (let i=0; i<5; i++) {
					if (this.doubtDidLiftCup[cc] || !this.bDiceHidden[cc][i]) {
						// this die is seen by all, examine it
						const die = this.dice[cc][i];
						if (bPaloFijo) {
							// if palofijo, only count ofWhat
							if (die === ofWhat) {
									result++;
							}
						} else {
							// not palofijo, count ofWhat and aces
							if (die === ofWhat || die === 1)  {
									result++;
							}
						}
					}
				}
			}
		}
		return result;
	}

	//****************************************************************
	// Does player have all 5 dice showing?
	//****************************************************************
	PlayerShowingAllDice (cc) {
		for (let i = 0; i < 5; i++) {
			if (this.bDiceHidden[cc][i]) {
				return false
			}
		}
		return true;
	}

	//****************************************************************
	// Did somebody just get a stick?  that we need to blink?
	//****************************************************************
	SomebodyGotStick () {
		// don't blink if these are true
		const numRounds = this.Rounds.length;
		if (numRounds === 0) {
			return false;
		}
		if (this.curRound.whichDirection !== undefined) {
			return false;
		}
		if (this.gamePhase === GAME_PHASE.CHOOSING_DIRECTION) {
			return false;
		}

		// did somebody just get a stick?
		if (this.GAME_IN_PROGRESS && 
       this.curRound.numBids === 0 &&
       !this.firstRound &&		// probably don't need this (overkill)
       !this.Rounds[numRounds - 1].doubtLoserOut) {
			return true;
		}
		return false;
	}

	//****************************************************************
	// Should all players roll? (starting round)
	//****************************************************************
	ShouldAllRollDice () {
			return this.GAME_IN_PROGRESS && this.curRound?.numBids === 0;
	}

	//****************************************************************
	// Get bid string
	//****************************************************************
	GetBidString(idx) {
		if (!this.curRound || this.curRound.numBids < 1) {
			return '';
		}
		if (idx < 0 || idx >= this.curRound.numBids) {
			return '';
		}

		let bidString = this.curRound.Bids[idx].text;
		let showed = this.curRound.Bids[idx].howManyShown;
		if (showed > 0) {
			bidString += ` (showed ${showed})`;
		}
		return bidString;
	}

	//****************************************************************
	// Get order of finish for the players
	// who came in 1st, 2nd, etc.
	//****************************************************************
	GetOrderOfFinish () {
    this.orderOfFinish.length = 0;
		
    // find players knocked out / timed-out in each round
    for (let i = 0; i < this.Rounds.length; i++) {
        const round = this.Rounds[i];

        // Players who timed out during this round
        if (round.timedoutPlayers) {
            for (const cc of round.timedoutPlayers) {
							// Special case: player timed out after already winning a game-ending doubt
							if (this.bWinnerGame && cc === this.whoWonGame) {
									continue;
							}
							// If this player was knocked out by the doubt,
							// record the elimination as "doubt", not "timeout"
							if (round.endRoundCause === ROUND_END_DOUBT &&
									round.doubtLoserOut &&
									cc === round.doubtLoser) {
									continue;
							}
							const guid = this.allParticipantGuid[cc];
							const name = this.allParticipantNames[cc];
							this.orderOfFinish.push({ cc, guid, name, reason: 'timeout'});
            }
        }

        // Player knocked out by the doubt result
        if (round.endRoundCause === ROUND_END_DOUBT &&
            round.doubtLoserOut) {

            const cc = round.doubtLoser;

						const guid = this.allParticipantGuid[cc];
						const name = this.allParticipantNames[cc];
						this.orderOfFinish.push({cc, guid, name, reason: 'doubt'});
        }
    }

		// add the winner
		const cc = this.whoWonGame;
		const guid = this.allParticipantGuid[cc];
		const name = this.allParticipantNames[cc];
		this.orderOfFinish.push({ cc, guid, name });

		// reverse so winner is first
		this.orderOfFinish.reverse();
	}
}

//****************************************************************
// DudoRound class
//****************************************************************
export class DudoRound {
	maxBids = 100;
	numBids = 0;
	curBid;		// one DudoBid object
	Bids = [];	// array of DudoBid objects
	timedoutPlayers = [];	// array of players that timeout during this round

	whichDirection = undefined;          // 1 = left (clockwise); 2 = right (counter-clockwise)
	startingPlayerIndex = -1;

	endRoundCause = undefined;					// ROUND_END_DOUBT or ROUND_END_TIMEOUT

	doubtedText = undefined;
	whoDoubted = undefined; 
	whoGotDoubted = undefined;   
	doubtHowMany = undefined;
	doubtOfWhat = undefined;
	doubtShowing = undefined;
	doubtLookingFor = undefined;
	doubtLoser = undefined;
	doubtWinner = undefined;
	doubtCount = undefined;
	doubtLoserPaloFijo = undefined;
	doubtLoserOut = undefined;
	doubtWasPaso = undefined;
	doubtPasoWasThere = undefined;

  constructor() {
    this.curBid = new DudoBid();
  }

	init() {
		this.whichDirection = undefined;
		this.startingPlayerIndex = -1;
		this.endRoundCause = undefined;

		this.doubtedText = undefined;
		this.whoDoubted = undefined;              
		this.whoGotDoubted = undefined;           
		this.doubtHowMany = undefined;
		this.doubtOfWhat = undefined;
		this.doubtShowing = undefined;
		this.doubtLookingFor = undefined;
		this.doubtLoser = undefined;
		this.doubtWinner = undefined;
		this.doubtCount = undefined;
		this.doubtLoserPaloFijo = undefined;
		this.doubtLoserOut = undefined;
		this.doubtWasPaso = undefined;
		this.doubtPasoWasThere = undefined;
	}
}

